using EFT;
using EFT.Interactive;
using Comfort.Common;
using CommonAssets.Scripts.Game;
using HarmonyLib;
using System.Reflection;
using System.Reflection.Emit;
using V=EscapeFromBorderlands.Client.BackpackVisitorExtraction;
int cases=0,checks=0,failures=0;
void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
void Near(float a,float b,string message)=>Check(Math.Abs(a-b)<1e-5,$"{message}: {a}!={b}");
void Run(string name,Action test){cases++;V.Reset();Singleton<GameWorld>.Instance=null;try{test();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e);}}
(Player Player,AbstractGame Game,ExfiltrationPoint Point,EndByExitTrigerScenario Scenario,GameWorld World) Setup(bool worn=true,bool shared=false)
{
 var p=new Player{WornKey=worn?V.Key:null};var point=new ExfiltrationPoint{Status=shared?EExfiltrationStatus.Countdown:EExfiltrationStatus.RegularMode,ExfiltrationStartTime=100};point.Settings.ExfiltrationTime=shared?60:5;point.Entered.Add(p);p.ExfiltrationPoint=point;
 var game=new AbstractGame();var scenario=new EndByExitTrigerScenario{_game=game};game._endByExitTrigerScenario=scenario;
 if(shared)scenario._monitoredEP.Add(point);else scenario._escapes.Add(new(p,point,100));
 var world=new GameWorld{MainPlayer=p};Singleton<GameWorld>.Instance=world;return(p,game,point,scenario,world);
}
MethodInfo Hook(string type,string method)=>typeof(V).Assembly.GetType("EscapeFromBorderlands.Client."+type)!.GetMethod(method,BindingFlags.Static|BindingFlags.NonPublic)!;
List<CodeInstruction> Transpile(string type,IEnumerable<CodeInstruction> codes)=>( (IEnumerable<CodeInstruction>)Hook(type,"Transpiler").Invoke(null,new object[]{codes})!).ToList();
var time=typeof(ExitTriggerSettings).GetField("ExfiltrationTime")!;var trigger=typeof(EndByExitTrigerScenario.LocationEscape).GetField("Trigger")!;var settings=typeof(ExfiltrationPoint).GetField("Settings")!;
List<CodeInstruction> NativeReads(CodeInstruction? load=null)=>new(){load??new(OpCodes.Ldloc_2),new(OpCodes.Ldfld,trigger),new(OpCodes.Ldfld,settings),new(OpCodes.Ldfld,time),new(OpCodes.Add),new(OpCodes.Ldfld,time)};
Run("Ordinary extraction durations are halved exactly while the pass is worn",()=>{var s=Setup();foreach(var d in new[]{0f,1f,5f,8f,10f,60f})Near(V.Duration(d,s.Player),d*.5f,"half duration");s.Player.WornKey=null;Near(V.Duration(5,s.Player),5,"removed pass");s.Player.WornKey="BP25-1";Near(V.Duration(5,s.Player),5,"different bag");Near(V.Duration(5,null),5,"no player");});
Run("Only the actual extraction entry's wearer receives the time change",()=>{var s=Setup();var other=new Player();Near(V.Duration(8,s.Player),4,"wearer");Near(V.Duration(8,other),8,"other actor");other.WornKey=V.Key;other.HealthController.IsAlive=false;Near(V.Duration(8,other),8,"dead player");});
Run("Run-throughs become Survived and other outcomes retain their semantics",()=>{var s=Setup();Check(V.Outcome(ExitStatus.Runner,s.Player)==ExitStatus.Survived,"run-through upgraded");foreach(var e in new[]{ExitStatus.Survived,ExitStatus.Killed,ExitStatus.MissingInAction,ExitStatus.Left,ExitStatus.Transit})Check(V.Outcome(e,s.Player)==e,"other outcome unchanged");s.Player.WornKey=null;Check(V.Outcome(ExitStatus.Runner,s.Player)==ExitStatus.Runner,"unworn bag");s.Player.WornKey=V.Key;s.Player.HealthController.IsAlive=false;Check(V.Outcome(ExitStatus.Runner,s.Player)==ExitStatus.Runner,"dead actor");});
Run("Shared exits queue only the wearer at the halfway deadline",()=>{var s=Setup(shared:true);var other=new Player();s.Point.Entered.Add(other);s.Game.PastTime=129.99f;V.QueueShared(s.Scenario);Check(s.Scenario.list_1.Count==0,"waits for halfway");s.Game.PastTime=130;V.QueueShared(s.Scenario);Check(s.Scenario.list_1.Count==1&&s.Scenario.list_1[0].Item1==s.Player,"only wearer queued");Near(s.Point.Settings.ExfiltrationTime,60,"shared setting unchanged");Near(s.Point.ExfiltrationStartTime,100,"shared start unchanged");Check(s.Point.Status==EExfiltrationStatus.Countdown,"shared point remains active");V.QueueShared(s.Scenario);Check(s.Scenario.list_1.Count==1,"no duplicate queue");});
Run("Shared shortcuts require presence, life, a worn pass and every native requirement",()=>{foreach(var failure in new[]{"not-worn","not-inside","dead","requirements","not-countdown","game-stopping","before-start"}){var s=Setup(shared:true);s.Game.PastTime=140;switch(failure){case "not-worn":s.Player.WornKey=null;break;case "not-inside":s.Point.Entered.Clear();break;case "dead":s.Player.HealthController.IsAlive=false;break;case "requirements":s.Point.Requirements=new[]{new Requirement(false)};break;case "not-countdown":s.Point.Status=EExfiltrationStatus.UncompleteRequirements;break;case "game-stopping":s.Game.Status=GameStatus.Stopping;break;case "before-start":s.Game.PastTime=90;break;}V.QueueShared(s.Scenario);Check(s.Scenario.list_1.Count==0,"native guard "+failure);}});
Run("The normal shared completion path remains in charge after its full deadline",()=>{var s=Setup(shared:true);s.Game.PastTime=161;V.QueueShared(s.Scenario);Check(s.Scenario.list_1.Count==0,"no duplicate native completion");s.Game.PastTime=160;V.QueueShared(s.Scenario);Check(s.Scenario.list_1.Count==1,"exact deadline allowed before native strict-greater check");});
Run("Ordinary UI countdown matches actual elapsed extraction time",()=>{var s=Setup();s.Game.UpdateExfiltrationUi(s.Point,true);Near(s.Game.Displayed,2.5f,"initial half timer");s.Game.PastTime=101;Near(V.UiDuration(5,s.Game,s.Point),1.5f,"remaining");s.Game.PastTime=103;Near(V.UiDuration(5,s.Game,s.Point),0,"clamps completed timer");});
Run("Shared UI applies the half duration before native elapsed subtraction",()=>{var s=Setup(shared:true);s.Game.PastTime=110;s.Game.UpdateExfiltrationUi(s.Point,true);Near(V.UiDuration(60,s.Game,s.Point),30,"duration before native subtraction");Near(s.Game.Displayed,20,"correct shared remaining");});
Run("Removing the pass refreshes the ordinary timer with the remaining normal duration",()=>{var s=Setup();s.Game.UpdateExfiltrationUi(s.Point,true);s.Game.PastTime=101;s.Player.WornKey=null;V.Maintain(s.World);Near(s.Game.Displayed,4,"normal duration minus elapsed");Check(s.Game.UiRefreshes==2,"one equipment refresh");V.Maintain(s.World);Check(s.Game.UiRefreshes==2,"no repeated frame refresh");Near(V.Duration(5,s.Player),5,"actual normal duration restored");});
Run("Equipping the pass during an existing extraction refreshes the shortened timer",()=>{var s=Setup(false);s.Game.UpdateExfiltrationUi(s.Point,true);Near(s.Game.Displayed,5,"normal initial");s.Game.PastTime=101;s.Player.WornKey=V.Key;V.Maintain(s.World);Near(s.Game.Displayed,1.5f,"shorter timer includes elapsed");});
Run("Removing the pass restores shared timing without changing the world clock",()=>{var s=Setup(shared:true);s.Game.PastTime=110;s.Game.UpdateExfiltrationUi(s.Point,true);Near(s.Game.Displayed,20,"fast shared remaining");s.Player.WornKey=null;V.Maintain(s.World);Near(s.Game.Displayed,50,"normal shared remaining");Near(s.Point.Settings.ExfiltrationTime,60,"raw shared duration untouched");});
Run("Leaving an extraction and session reset clear timer presentation state",()=>{var s=Setup();s.Game.UpdateExfiltrationUi(s.Point,true);s.Player.ExfiltrationPoint=null;V.Maintain(s.World);s.Player.WornKey=null;Near(V.UiDuration(5,s.Game,s.Point),5,"left context cleared");s.Player.WornKey=V.Key;s.Player.ExfiltrationPoint=s.Point;s.Game.UpdateExfiltrationUi(s.Point,true);V.Reset();s.Player.WornKey=null;Near(V.UiDuration(5,s.Game,s.Point),5,"raid reset cleared");});
Run("Unrelated exfil UI events preserve the current extraction context",()=>{var s=Setup();s.Game.UpdateExfiltrationUi(s.Point,true);V.ObserveUi(s.Game,new ExfiltrationPoint(),false);s.Player.WornKey=null;s.Game.PastTime=102;V.Maintain(s.World);Near(s.Game.Displayed,3,"active context survives another point's update");});
Run("The individual transpiler changes one player duration and preserves the shared field read",()=>{var input=NativeReads();var result=Transpile("BackpackVisitorCountdownPatch",input);Check(result.Count==input.Count+3,"three stack-safe instructions");var call=result.Single(c=>c.opcode==OpCodes.Call);Check(((MethodInfo)call.operand!).Name=="Duration","correct adapter");int ix=result.IndexOf(call);Check(result[ix-2].opcode==OpCodes.Ldloc_2,"uses native entry local");Check(((FieldInfo)result[ix-1].operand!).Name=="Player","loads entry wearer");Check(ReferenceEquals(result[^1],input[^1]),"shared deadline remains native");});
Run("Transpilers preserve native labels and local operands",()=>{var dm=new DynamicMethod("labelTest",typeof(void),Type.EmptyTypes);var il=dm.GetILGenerator();var local=il.DeclareLocal(typeof(EndByExitTrigerScenario.LocationEscape));var load=new CodeInstruction(OpCodes.Ldloc_S,local);load.labels.Add(il.DefineLabel());var input=NativeReads(load);input[3].labels.Add(il.DefineLabel());var result=Transpile("BackpackVisitorCountdownPatch",input);Check(ReferenceEquals(result[0],load),"native local load retained");Check(ReferenceEquals(result[4].operand,local),"injected local uses native builder");Check(result[4].labels.Count==0,"injected load has no duplicated branch label");Check(ReferenceEquals(result[3],input[3])&&result[3].labels.Count==1,"native duration labels retained");});
Run("Both extraction UI duration reads receive the scoped adapter",()=>{var input=new[]{new CodeInstruction(OpCodes.Ldfld,time),new CodeInstruction(OpCodes.Nop),new CodeInstruction(OpCodes.Ldfld,time)};var result=Transpile("BackpackVisitorCountdownUiPatch",input);Check(result.Count==9,"two three-instruction adapters");Check(result.Count(c=>c.opcode==OpCodes.Call&&((MethodInfo)c.operand!).Name=="UiDuration")==2,"both native branches covered");Check(result[1].opcode==OpCodes.Ldarg_0&&result[2].opcode==OpCodes.Ldarg_1,"game and point arguments match native stack");});
Run("Unexpected native countdown shapes reject the patch instead of changing the wrong timer",()=>{foreach(var input in new[]{new List<CodeInstruction>(),new(){new(OpCodes.Ldfld,time)},new(){new(OpCodes.Nop),new(OpCodes.Nop),new(OpCodes.Nop),new(OpCodes.Ldfld,time),new(OpCodes.Ldfld,time)}}){bool rejected=false;try{Transpile("BackpackVisitorCountdownPatch",input);}catch(Exception){rejected=true;}Check(rejected,"bad countdown IL rejected");}bool badUi=false;try{Transpile("BackpackVisitorCountdownUiPatch",Array.Empty<CodeInstruction>());}catch(Exception){badUi=true;}Check(badUi,"bad UI IL rejected");});
Run("The Stop prefix upgrades only the matching local player's successful run-through",()=>{var s=Setup();var method=Hook("BackpackVisitorSurvivedPatch","Prefix");object[] own={s.Player.ProfileId,ExitStatus.Runner};method.Invoke(null,own);Check((ExitStatus)own[1]==ExitStatus.Survived,"matching player upgraded");object[] other={"other-player",ExitStatus.Runner};method.Invoke(null,other);Check((ExitStatus)other[1]==ExitStatus.Runner,"other profile unchanged");});
Console.WriteLine($"Visitor's Pass client: {cases-failures}/{cases} cases passed; {checks} assertions; {failures} failures.");return failures==0?0:1;
